"use strict";

const http = require("node:http");

function readText(res) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    res.setEncoding("utf8");
    res.on("data", (chunk) => chunks.push(chunk));
    res.on("end", () => resolve(chunks.join("")));
    res.on("error", reject);
  });
}

exports.get = function get(url) {
  return new Promise((resolve, reject) => {
    const req = http.get(url, {
      headers: { "x-fixture": "http-get-client" },
      timeout: 1000,
    }, async (res) => {
      try {
        const body = await readText(res);
        resolve([
          "httpnpm.http-get=" + res.statusCode,
          res.statusMessage,
          res.headers["x-method"],
          res.headers["x-path"],
          body,
        ].join("|"));
      } catch (error) {
        reject(error);
      }
    });
    req.on("error", reject);
  });
};
